class Solution:
    def maxCaloriesBurnt(self, heights: List[int]) -> int:
        hs = sorted(heights)
        seq = []
        lo, hi = 0, len(hs) - 1
        take_high = True
        while lo <= hi:
            if take_high:
                seq.append(hs[hi]); hi -= 1
            else:
                seq.append(hs[lo]); lo += 1
            take_high = not take_high
        prev, tot = 0, 0
        for h in seq:
            tot += (prev - h) ** 2
            prev = h
        return tot

c.cpp:
class Solution {
public:
    long long maxCaloriesBurnt(vector<int>& heights) {
        vector<int> hs = heights;
        sort(hs.begin(), hs.end());
        vector<int> seq;
        int lo = 0, hi = hs.size() - 1;
        bool takeHigh = true;
        while (lo <= hi) {
            if (takeHigh) seq.push_back(hs[hi--]);
            else seq.push_back(hs[lo++]);
            takeHigh = !takeHigh;
        }
        long long prev = 0, tot = 0;
        for (int h : seq) { tot += (prev - h) * (prev - h); prev = h; }
        return tot;
    }
};

