class Solution {
    public long maxCaloriesBurnt(int[] heights) {
        int[] hs = heights.clone();
        Arrays.sort(hs);
        List<Integer> seq = new ArrayList<>();
        int lo = 0, hi = hs.length - 1;
        boolean takeHigh = true;
        while (lo <= hi) {
            if (takeHigh) seq.add(hs[hi--]);
            else seq.add(hs[lo++]);
            takeHigh = !takeHigh;
        }
        long prev = 0, tot = 0;
        for (int h : seq) { tot += (prev - h) * (prev - h); prev = h; }
        return tot;
    }
}

