var maxCaloriesBurnt = function(heights) {
    const hs = [...heights].sort((a, b) => a - b);
    const seq = [];
    let lo = 0, hi = hs.length - 1, takeHigh = true;
    while (lo <= hi) {
        if (takeHigh) seq.push(hs[hi--]);
        else seq.push(hs[lo++]);
        takeHigh = !takeHigh;
    }
    let prev = 0, tot = 0;
    for (const h of seq) { tot += (prev - h) ** 2; prev = h; }
    return tot;
};
